// Файл згенеровано scripts/build_tlumach.py з scripts/zigaben/uk/, не правте вручну.
import type { TlumPsalms } from './index';
// Кафизма 19: псалми 134–142.
export const Z: TlumPsalms = {"134":[{"v":"0","t":["Алилуя.","Про напис «Алилуя» ми говорили раніше, а саме, що псалми, які мають цей напис, — подячні Богові.","Прим.: За словами Євсевія, «алилуя» означає: хваліть Господа; бо «алилу» означає «хваліть», а «я» — «Господа»; тому цей псалом містить пісню й хвалу Богові; він же містить ще й початкове вчення, якого потребують ті, хто приходить до Божого слова з язичників; на них і поширюється це повеління, як на рабів, що ще не дістали Духа всиновлення й не ввійшли до найвнутрішнішої частини дому, а ще стоять поза тією частиною, до якої мають увійти тоді, коли стануть синами через Духа."]},{"v":"1","t":["Усі, каже, раби Господні, і як Його творіння, і як вірні та свої Йому, славте ім'я Господнє, бо воно освячує й благословляє тих, хто його благословляє. Але про це ми сказали й у 102-му псалмі.","Прим.: Слова Феодорита: оскільки єство Боже невидиме, а Він велить хвалити Його, то влучно сказав: хваліть ім'я Господнє; задовольняйтеся, каже, одним найменуванням Бога й не домагайтеся побачити те, чого не дозволено бачити."],"h":"Хваліть ім'я Господнє, хваліть, раби Господні"},{"v":"2","t":["Те саме сказав і в попередньому псалмі. Але тепер, спонукаючи всіх, хто входить до храму Божого, каже: прославляйте Бога, ви, що стоїте в храмі Божому, бо тим, хто не стоїть у храмі Божому, не дозволено хвалити Бога. Чому? Бо ті, хто бачить храм і в ньому Святе Святих, що є оселею Божою, ніколи не забувають Бога, а, навпаки, спонукаються до Його хвали.","Прим.: Цей мудрий тлумач цими словами не забороняє нікому хвалити Бога, коли він перебуває і в Його домі, і в будь-якому іншому місці, а заохочує ними християн іти до храму Божого й там молитися з іншими своїми братами, коли не заважає їм жодна потреба, ні хвороба, ні щось інше: бо молитва, яку християни приносять Богові одноголосно, буває Йому приємніша. Тому Золотоустий, пояснюючи це місце, каже: а якщо й уночі слід ходити до святині, то подумай, яке прощення дістане той, хто й удома в цей час не звершує молитви. Бо якщо в юдейському храмі не кожне місце було доступне для всіх, а були різні відділи, так що одне було призначене для прибульців, інше — для тих, хто був юдеями від початку, ще інше — для священиків, і ще інше — для самого архієрея, то подумай, яку святість потрібно мати тобі, що дістав набагато більше, ніж мало образів Святе Святих? Ти вже маєш не херувимів, а Самого Господа херувимів, що живе тут; і не посудину з манною, і не кам'яні скрижалі й Ааронів жезл, а Тіло й Кров Владики, і замість письмен — Духа. А що більших і страшніших таїнств ти сподобився, то більше зобов'язаний зберігати святість і то більшій кари підлягаєш, якщо переступиш те, що тобі звелено. Євсевій: добре сказано — стояти в домі Господньому й не хитатися, не відступати назад, а виявляти ревність до ходіння всередину. Феодорит: звільнившись, каже, від вавилонського рабства й досягнувши бачення краси Божих дворів, прославте піснями Подателя цих благ."],"h":"Ви, що стоїте в храмі Господньому, у дворах дому Бога нашого"},{"v":"3","t":["Славте, каже, Господа за Його людинолюбство, за те, що Він дуже благодійний для всіх, а особливо для тих, хто хвалить і славить Його. Співайте, веде далі, імені Господньому, бо добре й корисно співати Господеві духовні пісні й псалми; коли їх співають з розчуленням і благоговінням, вони навчають тих, хто співає й слухає, точності догматів, збирають до Бога, присипляють пристрасті, втішають злагодженістю душу й разом з користю, за словами Золотоустого, дають і приємність, і насолоду. Як ті, хто має любов до когось, складають якісь похвали й пісні йому, співом і читанням яких, за Золотоустим, задовольняють своє бажання, так і Давид, радячи співати, цим показує, що ті, хто співає й слухає, мають мати велику любов до Бога. До того ж сказав «співайте» не Божому єству, бо воно незбагненне, а Його імені, складаючи Йому хвали.","Прим.: Феодорита: приводом до співу, каже, зробіть благість Того, Кому співається пісня.","Прим.: Інший тлумач переклав: співайте імені Його, бо це пристойно, а ще інший: бо це солодко. І обидва вони, за словами Золотоустого, кажуть правду. Бо хоч би той, хто співає, був безмірно хтивий, соромлячись слів цього псалма, він приборкає жорстокість хтивості; хоч би був обтяжений незліченними лихами й охоплений смутком, захоплюючись приємністю, він полегшить свої думки, окрилить свій розум, зробить душу піднесеною. А псалтир, за словами Євсевія, — це людське тіло, складене з різних чуттів, ніби з різних струн, через яке розум людини, граючи злагоджено й правильно, звершує те, що стосується доброчесного життя. Отже, оскільки співати, каже, тобто славити ділами Бога, — добре, то приносьте Йому належну пісню через псалтир і тілесні члени."],"h":"Хваліть Господа, бо добрий Господь; співайте імені Його, бо це гарно"},{"v":"4","t":["Тут Давид викладає причину, з якої слід співати Господеві: вона полягає в тому, що Господь з усіх народів вибрав юдейський народ, що походить від патріарха Якова, і його відокремив для Себе, щоб він служив тільки Йому одному. Той самий юдейський народ тут називає Ізраїлем, бо він походить від Ізраїля, тобто від Якова: бо той самий, що раніше звався Яковом, згодом, за своїм поступом у Бозі, як пояснює Великий Василій, був названий і Ізраїлем. Юдейський, каже, народ Бог вибрав Собі у власність, тобто в спадщину й набуток Свій; тому Бог і назвав його Своїм власним народом: будете, каже, Мені власним народом (Вих. 19:5), тобто скарбом, улюбленим предметом Його піклування, мов майно й багатство."],"h":"Бо Якова вибрав Собі Господь, Ізраїля — на власність Собі"},{"v":"5","t":["Тут Давид подає й іншу причину, з якої мають хвалити Бога й співати Йому всі давні й нові ізраїльтяни, тобто християни: вона, каже, полягає в тому, що я більше за вас і точно збагнув, що Господь великий; а це я пізнав і від божественної благодаті, що мене просвітила, і через розглядання розумом Його діл і чудес. Господь, що шанується нами як Бог, — сущий, тобто справжній, а боги, так звані в еллінів, зовсім не існують; і Господь наш — справжній Господь, а боги еллінів не справжні. Далі слово «понад» тут, на перший погляд, ужите Давидом порівняльно, але це з передбачливістю, тобто, як зауважує Золотоустий, щодо грубості й низькості пізнання юдейського народу; а в інших місцях він називає Його Господом і Богом богів: Бог богів, Господь, промовив (Пс. 49:1); і в цьому ж псалмі, поступово підносячи слухачів до справжнього пізнання Бога, представляє Його Творцем і Звершителем чудес, а далі ганьбить язичницьких богів. І в 96-му псалмі сказано також: Ти дуже піднісся над усіма богами; там і дивись пояснення цих слів.","Прим.: Золотоустого: скажи ж мені: ти пізнав, а хіба інші не знали? Так, знали, каже, але не так, як я; бо точніше знання Його величі належить особливо святим і тим, хто піднісся, і то не все, як воно є, бо це неможливо, а ясніше, ніж іншим. Феодорита: з самих, каже, діл ми пізнали силу нашого Бога й те, що шановані в інших народів боги аж ніяк не можуть зрівнятися з Ним; бо ніхто не порівнює неіснуючого з існуючим і вічносущим."],"h":"Бо я пізнав, що великий Господь, і Господь наш — понад усіма богами"},{"v":"6","t":["Те саме сказав у 113-му псалмі: Бог наш на небі й на землі; усе, що схотів, сотворив. Давид морями називає різні затоки одного моря, бо збори вод Бог назвав морями (Бут. 1:10). А безоднями називає підземні, недосліджені. Усередині, каже, тих і інших Бог сотворив тварин, рослин, одушевлені й бездушні речі, що в них містяться, які Йому було вгодно. Далі він прославляє деякі дивовижні Божі діла, залишивши більші, щоб і з нижчих творінь показати велич і пам'ятність Творця.","Прим.: Феодорита: з цим згідне таке: з величі й краси творінь за міркуванням можна бачити Причину їхнього буття (Прем. 13:5); а також апостольські слова: бо невидиме Його від створення світу стає видимим через розглядання творінь. І Давид тепер із творіння показує Божу силу й каже, що їх створення відповідає не силі, а Його бажанню: бо Він міг створити багато разів стільки ж творінь і набагато більших, але Йому було вгодно створити стільки й таких властивостей. Золотоустого: і, що особливо дивовижно, Він сотворив без праці й напруги, не за наказом, а одним бажанням: варто було тільки захотіти — і раптом сталося саме діло. І як у нас бажання не спричиняє втоми, так і в Нього — створення стількох і таких великих сил. Це й пророк показав, кажучи: усе, що схотів, сотворив на небі й на землі. Чи бачиш, що не тільки для створення земних, а й для творення небесних сил досить було одного Його бажання? Чи помічаєш, як водночас представив і легкість, і рясноту творінь, і безперешкодну владу? Орігена: усі Господні творіння на небі й на землі, у морях і в безоднях, як такі, що постали з Божої волі, добрі. А хоч би хтось і став злим на небі, як-от духи злоби, чи на землі, як-от грішні люди, чи в морях, як злоба змія, чи в безоднях, як лукавство тих, кому звелено туди йти, — але цього зла Бог не сотворив за Своїм бажанням: бо з уст Всевишнього не може виходити і зло, і добро (Плач 3:38).","Прим.: Феодорита: безоднями називає безмірну безліч вод, а моря назвав у множині тому, що одне море ділилося на багато морів, як-от на затоки: Атлантичну, Тірренську й Іонічну, Егейську, Аравійську, Індійську, Евксинську та інші моря."],"h":"Усе, що схотів Господь, сотворив на небі й на землі, у морях і в усіх безоднях"},{"v":"7","t":["Господь, веде далі, Своїм промислом підіймає з найглибших місць землі хмари й так високо підносить їх у повітря за всієї їхньої природної ваги, і Він робить так, що вода, яка є в горішніх повітряних просторах, ллється з хмар, коли вони, згустившись, стануть важчими за повітря, що їх тримає. Бог, додає, творить під час дощу блискавки і влаштовує злагоду між протилежними речами, що знищують одна одну, без шкоди однієї від іншої, тобто так, що ні блискавка, попри свою вогненну й найполум'янішу властивість, не знищує й не висушує дощової води, ні, навпаки, дощова вода своїм швидким поривом не гасить блискавки, за Золотоустим і Феодоритом. Бог, додає, виводить вітри зі Своїх скарбниць; скарбницями називає приховані місця, з яких виходять вітри, бо скарб прихований; а образом скарбу Давид виражає невідомість походження вітрів. Або: виводить вітри ніби зі Своїх скарбниць, так що виражається легкість і зручність, з якою Бог, за словами Феодорита, творить їх, коли Йому вгодно. Бо справді дивно, що Бог так легко посилає то один, то інший вітер, або обидва разом, а інколи водночас і більше вітрів; а часто буває, що не посилає жодного, а стан і подих повітря становить тиша й безвітря; і все це Він робить для якоїсь потреби й з передбачливістю, а не без причини й марно, так що в Нього вітри ніби замкнені в якихось скарбницях, з яких Він виводить їх легко й коли Йому вгодно.","Прим.: Того ж: від країв землі, сказав, вони підіймаються, кажучи про це точно; бо вони складаються з морських вод, а краї землі — морські затоки. Бо моря обіймають землю; тому й сказано: що заснував землю на водах. А це сказано й у Йова: зв'язує воду в хмарах Своїх (Йов 26:8). Григорія Богослова: хто зв'язує воду в хмарах? Хто частину її зупинив на хмарах (хіба не дивно для зору, що текуча речовина утримується словом?) і іншу виливає на лице всієї землі й сіє свого часу й рівномірно? Василія: море служить якимсь початком і джерелом повітряних вод, коли нагрівається сонячним промінням і віддає від себе через випаровування тонкі частинки води, які, притягнені в горішній простір, потім охолоджуються. Бо, піднявшись далі, ніж сягає проміння, відбите земною поверхнею, коли в них посилюється холод, а також від тіні хмар, вони стають дощем і живлять землю (Бесіда 4 на Шестоднев, про збирання вод). Також: хмара — густе повітря, що складається з вологого випаровування від землі; потім, піднята вгору вітрами, діставши від них значне скупчення й достатню вагу через вологу, що в ній, вона спускає на землю краплі. Такої властивості дощі, що беруть початок від землі й через повітря знову падають на землю. Золотоустого: так хмари не тільки підіймаються, а й переходять і не в кожному місці, де з'являються, спускають дощ, а інколи, минувши країни й народи, проливають його в іншому місці.","Прим.: Феодорит і Євсевій замість «для дощу» переклали: для приготування дощів і громів, бо за блискавкою зазвичай іде грім. Григорія Богослова: яку можеш запропонувати мені любомудрість про блискавки й громи ти, що гримиш від землі й не блищиш навіть малими іскрами істини? Якісь випари, що виходять із землі й творять хмари, назвеш їхньою причиною? Чи якесь згущення повітря? Чи стиснення й зіткнення найтонших хмар, так що стиснення в тебе творить блискавки, а розрив — грім? І що це за вітер, який стискається, а потім, не знаходячи виходу, від тисняви творить сяйво, а від прориву — грім? Таким питанням і подивом Богослов дає зрозуміти, що ніхто не осягає точно Божих творінь (друге його слово про богослов'я).","Прим.: І Господь сказав про вітер і повітря: вітер віє, де хоче, і голос його чуєш, а не знаєш, звідки приходить і куди йде (Ін. 3:8); бо й вітер — рух, порив повітря; тому й Григорій Богослов сказав: я маю на увазі повітря — це велике, щедре багатство, що не відміряється за гідністю й добробутом, а, подібно до манни, ділиться й приймається вдосталь і подається рівною мірою, — цю колісницю крилатих істот, це сидіння вітрів. А вітри, за словами Золотоустого, різні: один тонший, інший грубіший, один холодніший, інший тепліший, один сухіший, інший вологіший. За новітніми спостереженнями, на Середземному морі віє шістнадцять вітрів, а на океані — удвічі стільки, тобто тридцять два."],"h":"Підіймає хмари від країв землі, блискавки творить для дощу, виводить вітри зі скарбниць Своїх"},{"v":"8","t":["Про це вражання єгипетських первістків ми сказали в 77-му псалмі; там і шукай пояснення слів: проклав стежку гніву Своєму й не пощадив від смерті душ їхніх. А сказавши «аж до худоби», цим виражає надзвичайну кару єгиптян.","Прим.: Золотоустого: що земля, небо й усе видиме користується Його людинолюбством, це показав і пророк згаданими словами. А щоб зробити юдеїв вдячнішими, викладає й подробиці, кажучи, що Бог, промишляючи про всіх загалом, виявив їм і деякі особливі благодіяння. Феодорита: про останню кару згадав першою, бо за нею вже настало їхнє звільнення."],"h":"Він вразив первістків єгипетських від людини до худоби"},{"v":"9","t":["Дивись щодо цього в згаданому 77-му псалмі слова 43-го вірша: як Він учинив у Єгипті знамення Свої й чудеса Свої на полі Цоану. Оскільки Давид вище згадав про десяту й найтяжчу кару — смерть первородних, то слід висновувати, що словами «знамення й чудеса» він за зв'язком указує на інші кари.","Прим.: Що означає «посеред тебе»? — каже Золотоустий. Відкрито, як каже й в іншому місці: учинив спасіння посеред землі; бо що посередині, те явне для всіх. І Феодорит: бо царство не могло звільнити фараона від кар, посланих Богом, але того самого лиха зазнали не тільки ті, хто був під правлінням царя, а й цар. Так і великому Мойсеєві сказав Бог усіх: ось Я вражу кожного первістка єгипетського — від первістка фараона, що сидить на престолі, до первістка невільниці, що меле на жорнах (Вих. 11:5)."],"h":"Послав знамення й чудеса посеред тебе, Єгипте, на фараона й на всіх рабів його"},{"v":"10","t":["Бог, каже, умертвив народи, що перешкоджали переходові євреїв і входові в землю обітовану, тобто амаликитян, моавітян, едомлян та інших, або й сім народів, що жили в Палестині. Утім, Давид говорить про це стисло й мимохідь. Бог, розповідає, умертвив правителів і царів вищезгаданих народів."],"h":"Він вразив багато народів і вбив царів могутніх"},{"v":"11","t":["Сигон, цар аморейський, був знаменитий багатством і військами, а Ог був відомий величиною свого тіла й мужністю. Бо розповідається, що він мав залізне ложе, на якому спав, завдовжки дев'ять ліктів, а завширшки чотири лікті. Бог, каже, зруйнував усі царства землі ханаанської, тобто Палестини, у якій один народ жив окремо від інших і звався ханаанським.","Прим.: Мойсей ясно викладає це в Повторенні Закону: бо тільки Ог, цар башанський, залишився з рефаїмів. Ось ложе його — ложе залізне; ось воно в Раббі синів Аммонових: дев'ять ліктів його довжина й чотири лікті його ширина, ліктем людським (Повт. 3:11). А в Євфимія й у Феодорита написано, що його ложе було п'ять ліктів завширшки, — здається, через помилку переписувача.","Прим.: За словами Феодорита: хеттеїв, ханаанеїв, періззеїв, хіввеїв, амореїв, ґірґашеїв, євусеїв і двадцять дев'ять царів; і країни, які вони займали, та їхні міста Він розділив народові єврейському."],"h":"Сигона, царя аморейського, і Ога, царя башанського, і всі царства ханаанські"},{"v":"12","t":["Давид двічі повторив «спадщина», щоб показати її багатство й достаток, ніби сказавши: дав Своєму народові Ізраїлеві землю вищезгаданих народів у спадщину — справді у спадщину.","Прим.: Золотоустого: і це найбільше чудо, що вони змогли не тільки вигнати, а й заволодіти землею й розділити міста, і це дало їм найбільшу насолоду, окрасу, славу. Феодорита: Бог Ізраїлів дав їм, мов якусь батьківську спадщину, ту землю, яку здавна займали ці нечестиві царі."],"h":"І дав їхню землю у спадщину, у спадщину Ізраїлеві, народові Своєму"},{"v":"13","t":["За вищезгадані, каже, чудеса, сотворені Тобою, Господи, Твоє ім'я й пам'ять про Тебе перебуватимуть повік і в усіх родах у євреїв, бо вони дістали благодіяння через ці чудеса.","Прим.: Золотоустого: тут уриває зв'язок мови славослів'ям, що зазвичай роблять святі: коли, почавши говорити про якесь з Божих чудес, вони запалюються, то не раніше закінчують свою мову, ніж прославлять і похвалять Бога за те, про що говорилося, і так задовольняють своє бажання; це особливо робить усюди й Павло. Запалившись невимовним Божим людинолюбством, Давид виголосив славослів'я: Господи, ім'я Твоє повік, тобто слава Твоя безперервна: ніщо не може пошкодити чи перервати її; вона стала, незмінна, непорушна, у повному яскравому світлі. І пам'ять про Тебе, тобто пам'ять, що в Тебе, не скінчиться протягом усіх родів, вона безмежна. І Феодорита: величина сотворених Тобою чудес показала всім Твоє ім'я, і пам'ять про Твої благодіяння збережеться в усіх майбутніх родах."],"h":"Господи, ім'я Твоє повік, і пам'ять Твоя з роду в рід"},{"v":"14","t":["Бог, веде далі, судитиме Свій народ, тобто звершить за нього суд і відплату ворогам, що йому шкодили, і схилиться до Свого народу, який благає й пом'якшує Бога своїми молитвами. Або, за словами Золотоустого, Бог судитиме Свій народ, коли він згрішить, і праведно покарає його, а коли знову покається, Він змилосердиться над ним і допоможе йому.","Прим.: Слова Феодорита: Ти, каже, не знехтуєш нами, з якими перед Твоїм поглядом воюють вороги, і не наведеш кар, на які ми заслуговуємо за наші гріхи, а будеш милостивий і поблажливий. Зауваж же, що ці слова Давид запозичив у Мойсея з його пісні: бо судитиме Господь народ Свій і над рабами Своїми змилосердиться."],"h":"Бо судитиме Господь народ Свій і над рабами Своїми змилосердиться"},{"v":"15","t":["Те саме сказано й у 113-му псалмі; там і дивись пояснення цього. А якщо хтось заперечить, за зауваженням премудрого Фотія, що й наші християнські святі образи — срібло й золото за речовиною й діло рук людських, на це відповідаємо, що хоча й вони — діло рук людських, але не ідоли; бо першообрази ідолів не існували й фальшиві, адже вони представляють вигляд тих богів, які не боги, а біси, що брешуть і вигадують божество; а першообрази наших святих ікон дійсні й справжні, як і іменуються. До того ж ідоли — зображення мерзенних і нечистих, а ікони — образи святих і чистих.","Прим.: Золотоустого: оскільки на початку сказав «Господь наш понад усіма богами» і цим комусь могло видатися, що, кажучи так, пристосовуючись до немочі слухачів, він показує перевагу лише порівняльно, то дивись, як він продовжує слово. Феодорита: назвав їх вище богами, а тепер показує, що вони, будучи без дійсності, позбавляються й самого найменування; він так каже: наш Бог, прекрасні й добрі раби Господні, — Бог усіх, і великий, і Творець, що творить велике; Він сотворив те й те; а боги язичників не тільки не мають творчої сили, а й сам свій вигляд дістали від людського мистецтва, а отже, вони були не що інше, як мертві й глухі ідоли, сутність яких — бездушна речовина, а діло — людське заняття, і їхній вигляд не має жодної дії. Тому й каже золотий святитель, що найбільший докір для тих, хто їм служить, — що вони, будучи й причиною їхнього буття, на них покладають надію свого спасіння."],"h":"Ідоли народів — срібло й золото, діло рук людських"},{"v":"16-17","t":["Те саме сказав і в 113-му псалмі; там і дивись їх пояснення. Тут Давид викладає й причину, з якої язичницькі ідоли безчутні: вони, каже, тобто ці ідоли, не мають подиху життя. Далі Давид поширює цю насмішку над ідолами, щоб ще більше їх присоромити."],"h":"Уста мають — і не говорять, очі мають — і не бачать, вуха мають — і не чують, і немає подиху в устах їхніх"},{"v":"18","t":["Ці слова пояснені в 113-му псалмі; там можеш побачити їхній зміст.","Прим.: Золотоустого: подумай, які ті боги, уподібнення до яких поставлено нарівні з прокляттям; а наше не таке. Бо уподібнення Богові, наскільки це для нас можливо, — найвища межа чесноти й досягнення найвищих благ. Влучно також висловився й Симмах у Євсевія: подібними до них стануть ті, що роблять їх; бо справді ті, хто вдається до бездушних богів, як скам'янілі душею, дійшли до стану тих, кому поклоняються. Феодорита: такої безчутності гідні ті, хто їх робить і їм поклоняється. Бо ті, хто, сам маючи розум, вважає богами тих, хто не має життя й розуму, справедливо стає учасником їхнього нерозуміння."],"h":"Нехай подібні до них будуть ті, що роблять їх, і всі, що надіються на них"},{"v":"19-20","t":["І в 113-му псалмі зробив такий самий поділ народу; там і шукай пояснення цього. Але там написано «дім Ізраїлів надіявся на Господа», а тут — «благословіть Господа», тобто дякуйте Господеві за вищесказані благодіяння, які Він вам зробив. До того ж тут поділив коліно освячених на дві частини: на дім Ааронів, який окремо був першоначальником священних осіб, і плем'я Левія, що був родоначальником і Аарона, і левитів, тобто тих, хто служив, як диякони, у скинії, — роблячи це слово загальнішим і яснішим через Левія.","Прим.: Золотоустого: чому не закликає всіх разом, а з поділом на частини? Щоб ти через це пізнав велику різницю між благословеннями. Інакше благословляє священик, інакше левит, інакше мирянин, інакше численний народ. Благословіть, каже, за ваше звільнення від ворогів, за те, що сподобилися поклонятися Богові. Хоча Він має в Своєму єстві благословення й не потребує хвали інших, утім і ви благословіть, не маючи думки, ніби щось додаєте Йому, а що самі дістаєте від цього користь. Феодорита: вони, каже, приносять бездушним ідолам таке служіння, а ви прославляйте Творця всіх. Далі Давид відокремив левитів (які були дияконами й служителями) від священиків, бо, хоча вони були шанованіші за інших, але нижчі за священиків. Отже, щоб і вони не намагалися захопити собі священичої гідності, як у давнину зважилися на це за проводу богонатхненного Мойсея, конче потрібно було відрізнити їх від священиків. А іншим був чин тих, хто боїться Бога, що походив від Якова й наслідував його благочестя. Далі до благочестивих зараховували й прибульців, тобто прозелітів. І це давало зрозуміти юдеям, що Бог усіх ставить моральну спорідненість вище за знатний рід."],"h":"Доме Ізраїлів, благословіть Господа; доме Ааронів, благословіть Господа; доме Левіїн, благословіть Господа; ті, що боїтеся Господа, благословіть Господа"},{"v":"21","t":["Нехай, підсумовує, Господь буде благословенний і прославлений із Сіону, тобто Той, Хто живе на Сіоні й живе в єрусалимському храмі. Бо там, як говорилося, живе Господь, бо Він розмовляє з очищальника ковчега зі священиками.","Прим.: Золотоустого: хоча Він благословенний за природою, як і існує, але хоче, щоб і ми благословляли Його. Феодорита: Бог, коли Його благословляють, благословить; але Його благословляють словом, а Він благословить самим ділом; і ті, хто прославляє Його, приносять слова, а Він віддає благословення й благодать ділами. А сказав, що Він живе в Єрусалимі, не тому, що обмежує Його природу, а тому, що знав про Його божественне явлення там."],"h":"Благословенний Господь із Сіону, що живе в Єрусалимі"}],"135":[{"v":"0","t":["Алилуя.","І цей псалом одного змісту з попереднім, за зауваженням Феодорита; тому й має той самий напис."]},{"v":"1","t":["Дякуйте, починає, Господеві, раби Господні, за ті самі Його благодіяння, про які згадав у попередньому псалмі. Такий самий початок зробив Давид і в 105-му псалмі, сказавши: сповідуйтеся Господеві, бо Він благий, бо повік милість Його; там це нами пояснено. Понад те, усі вірші цього псалма закінчуються словами «бо повік милість Його» — або для примноження такої Божої милості, або для хвали, щоб справити сильне враження й подив у тих, хто її оспівує.","Прим.: Слова Золотоустого: після кожного вірша додає, мов приспів: бо повік милість Його, тобто не так, як буває з людьми, що інколи благодіють, а інколи перестають. Людям і недуга заважає це робити, і бідність перешкоджає; а Він безперестанно милує, постійно милостивий і ніколи не припиняє цієї справи. Феодорита: принесіть, каже, Богові вдячний спів, згадуючи дані Ним блага й дивуючись Його безмірній милості. Зауважимо тут, що цей псалом власне зветься многомилостивим, тобто полієлейним, від милості, що багато разів згадується в ньому після кожного вірша. А від цього псалма дістав ім'я полієлейного й попередній псалом, тобто «Хваліть ім'я Господнє». І саме панікадило, тобто багатосвічник, що висить посеред церкви, також назване від цього псалма полієлеєм, бо його запалюють під час співу многомилостивого псалма. Тому за кожного співу першого псалма неодмінно слід співати нерозривно за ним і цей псалом, як власне полієлейний, і не можна співати тільки першого без другого, як нерозважливо й погано роблять інші."],"h":"Славте Господа, бо Він добрий, бо повік милість Його"},{"v":"2","t":["Дякуйте, веде далі, Богові, Який є Богом і Владикою над фальшиво іменованими богами й бісами, яким елліни поклоняються як богам; бо хоча біси безчесні й вороги Божі, як перші причини зла й противники Божі, але все ж вони слуги Божі за творінням і в цьому відношенні неминуче підвладні Богові.","Прим.: Євсевія: Він — Бог богів, не тільки бісів, а й тих, про кого сказано: Я сказав: ви боги; а також: богів не лихослов; бо й ангели можуть бути названі богами; тому й апостол каже: бо є багато богів і багато господ на небі чи на землі (1 Кор. 8:5). Орігена: після Трійці так звані боги є такими й звуться такими через причастя Божества (тобто Божої дії й благодаті, а не Божого єства). А Спаситель — Бог не через причастя, а за сутністю. Феодорита: називає богами тих, хто вшанований саном священства, бо вони стали синами Божими. Так і в псалмах: Я сказав: ви боги й сини Всевишнього всі."],"h":"Славте Бога богів, бо повік милість Його"},{"v":"3","t":["Дякуйте, додає, істинному Господеві всіх тимчасових, земних і несправжніх господів, бо наш Господь — Цар царів і Господь господів."],"h":"Славте Господа господів, бо повік милість Його"},{"v":"4","t":["Дякуйте, спонукає, Господеві, Який один сотворив великі чудеса; «один» додано не для відмежування від Сина й Духа, бо Господом називає одного Бога, що шанується в трьох Особах.","Прим.: У Золотоустого пишеться «що творить», у таких його словах: оскільки раніше сказав, що Він — Господь і Владика богів, то на це висловлювання тепер наводить доказ і підтверджує сказане про Нього проповіддю про Його силу. І не сказав «що сотворив», а «що творить», кажучи, що Він благодіє й творить чудеса. До того ж уживає цей дієприкметник двічі, а краще — тричі й чотири рази: і що Він творить, і що творить чудеса, і що великі чудеса, і що творить один. Бо, за зауваженням Феодорита, і чудеса Його друзів і угодників — Мойсея, Ісуса Навина й Іллі — належать Богові. Для чого ж на початку (питає Золотоустий) Давид не говорив про могутність, що слід благословляти Бога за неї, а за те, що Він добрий? Чому ж тепер раптом почав говорити про силу? Тому, що ці чудеса показують не тільки силу, а й благість і людинолюбство."],"h":"Тому, Хто один творить великі чудеса, бо повік милість Його"},{"v":"5","t":["Дякуйте, радить, Господеві, Який премудрістю сотворив небеса; цими словами Давид свідчить про благість і милість, що в Бозі, і про панування над усіма, і про силу та премудрість, які Бог має за природою.","Прим.: Василія: з цими словами згідні такі: Бог премудрістю заснував землю, утвердив небеса розумом. А розум, яким приготовлені й утверджені небеса, — який може бути інший, як не Христос? Бо Христос — Божа сила й Божа премудрість. Золотоустого: сотворив не одне тільки небо, а й інше, від самого початку показуючи цим, що Він не хоче залишити нас на землі, а переселити туди. Бо якби в Нього не було наміру переселити туди, то для чого Він створив за Своїм бажанням небо? Бо Йому ця стихія не потрібна; але, бажаючи переставити туди тих, хто на землі, Він приготував для них оселі."],"h":"Тому, Хто сотворив небеса мудрістю, бо повік милість Його"},{"v":"6","t":["Дякуйте, навчає, Господеві, Який утвердив землю на водах; і про це дивись у 23-му псалмі слова «Він на морях заснував її», і там знайдеш пояснення цього місця.","Прим.: Золотоустого: яка дивна властивість і понадприродний порядок у цьому творінні! Бо за порядком природи — щоб вода трималася на землі, а не земля на водах. До того ж як часто малому каменю, що впав у воду, вона поступається, розступається й пропускає його в саму безодню. Отже, коли ти побачиш, що не малий камінь, а вся земля тримається на поверхні вод і не тоне, то подивуйся силі, що так понадприродно це влаштувала. Євсевія: що найдивовижніше — земля, стихія щільна й важка, носиться й пливе на водах, тоді як ці тіла не такої властивості; бо мокрі, як легші за землю, мають триматися вище за неї, а вона, як стихія важка й груба, має опускатися й ховатися під глибинами мокрого тіла. Але в складі світу робиться не це, а навпаки, всупереч законові природи."],"h":"Тому, Хто утвердив землю на водах, бо повік милість Його"},{"v":"7-9","t":["Дякуйте, каже, Господеві, Який сотворив два великі світила: світило більше — для панування над днем, і світило менше — для керування ніччю; і поставив їх Бог на небесній тверді, щоб світили на землю й керували днем і ніччю (Бут. 1:16–18).","Прим.: Феодорита: влучно з кожним словом піснописець поєднує вічну милість, бо Людинолюбець сотворив усе не з потреби, а з однієї благості. Золотоустого: те, що створені такі великі світила, прекрасні й достатні, показує силу й премудрість, а те, що створені для нас і для нашої користі, — явно відкриває вічну благість. Василія: ці світила великі не тому, що більші за менші зорі, а тому, що мають обсяг, достатній для того, щоб промінням, яке з них виливається, осявати небо й повітря й водночас поширюватися на всю землю й море. Його ж: одне — благодійність світла, а інше — тіло, у якому перебуває світло. Бо це сонце, тобто сонячне коло, і це найсвітліше світло, бувши різними за природою, поєднані силою їхнього Творця. А день — міра часу, протягом якого сонце в півкулі перебуває над землею; а що вдень — тінь, те вночі становить природу темряви. Золотоустого: дивись, яка дивовижність у сонці. Вогонь за природою прагне вгору, завжди сильно підноситься на висоту, постійно рветься; і хоч би ти вжив незліченних способів примусу й насильства, він не може втриматися від прагнення від землі вгору. Так багато разів, узявши запалену скалку й раптом повернувши її вниз, ми не могли змусити вогонь звернути свій порив туди ж: він усе підіймається вище й знизу силкується бігти вгору. А з сонцем Бог учинив зовсім навпаки: Він звернув його проміння до землі й змусив світло прагнути вниз, ніби наказуючи йому так: дивись униз, світи людям."],"h":"Тому, Хто один сотворив світила великі, бо повік милість Його; сонце — для панування вдень, бо повік милість Його; місяць і зорі — для панування вночі, бо повік милість Його"},{"v":"10-12","t":["Дякуйте, навчає, Господеві, Який покарав Єгипет з його первородними синами й худобою і звільнив з-посеред Єгипту Свій народ Ізраїля міцною рукою й раменом, тобто високою рукою, інакше — великою й нездоланною силою; бо ці знамення, що Він їх сотворив у Єгипті, і Його чудеса, і вихід та звільнення єврейського народу були наслідками великої сили.","Прим.: А Феодорит, питаючи, каже: а якщо хтось заперечить: як милість може бути причиною смерті? — то той, хто шукає розв'язання цього, нехай зважить на те, що Він карає кривдників зі співчуття до скривджених; бо милість до ізраїльтян піддала єгиптян карі. І перша, і друга розчинені в Нього правосуддям: і тих Він милує праведно, і цих карає так само праведно. Тому й до того, й до іншого додано: бо повік милість Його. Євсевія: під міцною рукою й простягненим раменом розумій Боже Слово. Золотоустого: а це сказав для того, щоб хтось із недоумкуватіших не подумав, що, коли Він велів їм узяти золото й срібні посудини, то зробив це з безсилля. Бо й це зробив з тим наміром, щоб з усіх боків показатися страшним ворогам і показати, що все може робити повновладно — і обманювати їх, і хитро зводити. Бо як у тому випадку, коли щось робив відкрито, чинив так не тому, що не міг учинити хитро, так і в тому, коли щось зробив хитро, чинив так не тому, що не міг узяти відкрито, а щоб в обох випадках показати Свою силу. А що й це навело страх на іноплемінників, то послухай, що кажуть після того филистимські ворожбити: хіба не тоді, як Він насміявся з них, вони відпустили їх, і ті пішли? (1 Сам. 6:6)."],"h":"Тому, Хто вразив Єгипет з первістками його, бо повік милість Його; і вивів Ізраїля з-посеред них, бо повік милість Його, рукою міцною й раменом простягненим, бо повік милість Його"},{"v":"13-15","t":["Дякуйте, радить, Господеві, Який розділив Червоне море на два відділи, тобто на дві частини; бо Він розділив його надвоє й провів ізраїльський народ посеред нього, а фараона та його військо струсив у нього й потопив їх; струшенням називає вкидання й потоплення, як усе широко викладає книга Вихід: бо струсив, каже, Господь єгиптян посеред моря (Вих. 14:27).","Прим.: Золотоустого разом з Євсевієм: за усним, тобто ненаписаним переданням євреїв, дорога була не одна, а для кожного коліна вода розділялася окремо, так що було дванадцять розтинів і поділів за числом колін. Феодорита: море, поділившись навпіл, замість одного склало два. Бо вода стала для них стіною праворуч і стіною ліворуч. Тому поділ моря надвоє назвав відділами. Але в іншому місці він же погоджується із Золотоустим і Євсевієм і каже: а краще, Бог вирівняв дороги, як, наприклад, ізраїльтянам, як каже Давид: Тому, Хто розділив Червоне море на частини. При цьому деякі додають, що простір розділеного Червоного моря, що тягнувся від одного краю суші до іншого і яким пройшли ізраїльтяни, на думку деяких, був завширшки двісті п'ятдесят стіп, а завдовжки одну лігу, тобто чотири милі, і цей простір євреї пройшли за шість годин. А інші твердять, що Писання назвало поділи в множині за властивістю єврейської мови, яка вживає множину замість однини. Бажаючи, каже Оріген, показати легкість потоплення, ужив вислів «струсив». Золотоустий: зауважте, як разом із силою й обуренням показав і довготерпіння, бо Він доти не винищував їх, хоч вони й були такі безсоромні й уперті, доки вони самі не кинули себе добровільно в погибель. Та сама Божа сила вдихнула в ізраїльтян після розступлення моря сміливість і змусила ступити на цю нову й дивну дорогу; бо оскільки в обох відділах води стояли горами, то для того, щоб не боятися й навіть не підозрювати небезпеки цього переходу, — що моря, нависаючи з обох боків, заллють їх і потоплять увесь народ, — потрібна була висока й мужня душа; тому й Давид сказав: і провів Ізраїля посеред нього."],"h":"Тому, Хто розділив Червоне море на частини, бо повік милість Його; і провів Ізраїля посеред нього, бо повік милість Його; і струсив фараона й військо його в Червоне море, бо повік милість Його"},{"v":"16","t":["Дякуйте, навчає, Господеві, Який провів ізраїльський народ через Червоне море й увів його в пустелю: бо й це введення Богом Свого народу в пустелю й збереження його там, де було стільки причин для його загибелі — голод, спрага, бездощів'я, надмірна спека сонця, безліч диких звірів та інші подібні безіменні небезпеки, від яких Бог зберіг їх неушкодженими, — це, за словами Золотоустого, таке чудо, що було не менше за розділення Червоного моря. Інші чудеса Давид пропускає, залишивши кожному читати про них з роздумом у книгах Мойсеєвих.","Прим.: За словами Золотоустого, Євсевія й Феодорита, і це показує божественну силу, що стільки народу Він протягом такого довгого часу живив у пустелі й водив без лиха, даючи їм з надлишком усе потрібне. Це чудо не менше за проведення через море. Бо, позбавлені всього, чого потребує людина, не маючи ні покрівлі, ні плаща, ні достатньої одежі, ні взуття, ні нічого іншого такого, вони проходили ту пустелю, ніби святкуючи посеред міст."],"h":"Тому, Хто провів народ Свій пустелею, бо повік милість Його"},{"v":"17-20","t":["Прим.: Феодорита: країна Башан — це те, що нині в Юдеї зветься Батанеєю. Пояснення Великого Василія у вищому розумінні: ім'я Башан розуміють у значенні сорому. Тому й цар Башану зветься Огом, що означає загорожа; бо соромні діла загороджують нам дорогу до спасіння. Бо всі, хто чинить соромні діла, перебувають під правлінням царя Ога, що відокремлює їх від Бога (тобто диявола), якого Господь розтрощує для звільнення його підвладних. А Сигон означає спокусу, тобто роздратування. Амореї означають балакучих або тих, що огірчують; їхнє винищення пророк Давид ставить на доказ Божої милості, бо їхню країну через це дано євреям на добре поселення; і це означало обертати багатства нечестивих на скарб праведних (Прип. 13:22). Інший, тобто Никита у Зводі: якщо хочеш бачити, що предивна Божа сила продовжує свою дію й донині, то перейди думкою до народу з язичників, і пізнаєш, як Він звільнив язичницький рід, що увірував у Христа, від гіркого рабства — не в єгиптян, а в лихих бісів, і вивів з єгипетської темряви, і переставив у світло, винищивши невидимих царів і злі сили, що раніше над ними панували, набагато лютіші за фараонових; від них Він і нас звільнив, творячи один великі чудеса Своїм раменом і правицею; про це сказав Ісая: відкриє Господь Бог святе рамено Своє перед усіма народами (Іс. 52:10)."],"h":"Тому, Хто вразив великих царів, бо повік милість Його; і вбив могутніх царів, бо повік милість Його; Сигона, царя аморейського, бо повік милість Його; і Ога, царя башанського, бо повік милість Його"},{"v":"21-22","t":["Усе це пояснено в попередньому псалмі; там і дивись пояснення."],"h":"І дав їхню землю у спадщину, бо повік милість Його; у спадщину Ізраїлеві, рабові Своєму, бо повік милість Його"},{"v":"23-24","t":["Господь, сповідує, згадав про нас, юдеїв, коли ми були пригноблені, тобто страждали в Єгипті: бо добре, каже, бачив Я страждання народу Мого в Єгипті й зійшов, щоб вирвати їх з руки єгиптян (Вих. 3:7–8). А кажучи «нас», Давид цим указує на своїх предків у Єгипті й приймає їх до себе через спорідненість з ними. Далі, залишивши інші окремі благодіяння, які Бог зробив євреям, знову звертається до загального Божого промислу й благодіяння.","Прим.: «В упокоренні нашому» — не в наших подвигах і не в добробуті, а в упокоренні, тобто саме наше нещастя й страждання могло схилити Бога, за словами Золотоустого. Слова Феодорита: про це згадує й Мойсей: застогнали, каже, сини Ізраїлеві від робіт, і зойк їхній зійшов до Бога (Вих. 2:23)."],"h":"Бо в упокоренні нашому згадав нас Господь, бо повік милість Його; і визволив нас від ворогів наших, бо повік милість Його"},{"v":"25","t":["Господь, веде далі, дає належну їжу всякому родові і людей, і всіх тварин — земних, морських і земноводних.","Прим.: Слова Золотоустого: дає їжу не тільки праведникам і тим, хто подвизається в правоті, а й грішникам, і нечестивим, і всьому людському родові. Отже, урожайність залежить не від землі, і не від вод, не від повітря, не від проміння й не від чогось іншого, а все від Нього. І з цього роби висновок не тільки про силу, а й про невимовне людинолюбство. Феодорита: дає їжу не тільки людям, а й безсловесним, відповідно до природи кожного, як сказано: погляньте на птахів небесних: вони не сіють, не жнуть, не збирають у засіки, а Отець ваш Небесний годує їх. Тож Божий промисел такий великий і достатній, що поширюється від чудес на небі до землі й до найменших тварин на ній."],"h":"Тому, Хто дає їжу всякій плоті, бо повік милість Його"},{"v":"26","t":["Дякуйте, підсумовує, Господеві Богові, Творцеві й Владиці неба. А коли Він — Творець неба, то, безперечно, і землі. Або сказав «небесного» тому, що Бог зветься таким, що живе на небі. Ми можемо прикласти і цей, і попередній псалом до себе й спонукати одне одного дякувати Богові, Який по-різному благодіяв Своєму давньому народові, скинув Своїх ворогів і сотворив усі вищезгадані чудеса. А якщо пояснюватимемо цей псалом у вищому значенні, то Яковом і Єрусалимом можна назвати новий, вибраний християнський народ, а Єгиптом — нечестя й гріх; знаменнями й чудесами посеред нього — чудеса, сотворені Христом, апостолами та іншими святими; фараоном — диявола, а рабами фараона — бісів і людей, що служать бісам. Далі вражені й розтрощені численні народи можемо назвати полчищами бісів, а Сигоном та Огом — самого сатану й другого після сатани; ханаанськими царями — гріховні влади. Під їхньою землею, даною новому Ізраїлеві, можемо розуміти ті місця, у яких раніше панували демони й з яких потім вигнані; під домом Ізраїлевим — загалом увесь християнський народ; під домом Аароновим — архієреїв і священиків, а під домом Левіїним — дияконів; під тими, хто боїться Господа, — доброчесних і праведних. Далі під іменем Сіону — Церкву Христову; під первістками єгипетськими — найсолодші й найприємніші пристрасті, як-от особливо тілесні, або те, що особливо бажане для бісів, як і первородні діти бажані для батьків. Під Червоним морем можемо уявляти солодкість і гіркоту нечестивих учень, якими оточуються й тонуть невіруючі й нечестиві; під пустелею — неплідність омани, пройшовши яку й звільнившись від якої благочестиві християни досягають плідної істини. Там же під упокоренням ми маємо розуміти наше християнське смирення — не тільки те, якого нам мимоволі завдають спокуси, а й доброчесне, тобто чесноту смирення, що звершується нашим вільним вибором.","Прим.: Феодорита: отже, Бог — Бог усіх, як Творець усіх; але Він переважно зветься Богом неба, бо особливо шанується служінням ангелів, що там живуть. Бо ця країна чиста від гріха. Отже, за все, каже Золотоустий, віддаваймо Богові подяку — за загальні й за окремі блага; ця жертва, це приношення найбільше може схилити Його до милості до нас."],"h":"Славте Бога небесного, бо повік милість Його"}],"136":[{"v":"0","t":["Псалом Давидів (через Єремію).","Цей псалом мовиться від імені левитів, тобто дияконів, і всього священичого племені та співців, що були полоненими у Вавилоні; і він же передрікає вищезгаданим юдеям, що мало з ними статися, навчаючи водночас, які слова вони мають вимовляти й які діла чинити, щоб ними схилити Бога до милості. У євреїв і він без напису.","Прим.: Зауваж, що, за словами Євсевія, у деяких списках на цьому псалмі є напис: «Аггея й Захарії». А Феодорит зауважує: деякі, зважившись на зухвалу справу, зробили на цьому псалмі напис «через Єремію». Але Єремію не відвели з полоненими до Вавилону, а він, проживши деякий час в Єрусалимі, з примусу беззаконних юдеїв брав з ними участь у переселенні до Єгипту. Тож як він міг казати: на ріках вавилонських, там ми сиділи? І Феофілакт Болгарський у передмові до тлумачення на Йону каже, що богонатхненного Єремію вавилонський цар Навуходоносор ушанував, запропонувавши йому обрати собі місце проживання; і тоді, як усіх інших царів і начальників відвів у полон, йому одному дав волю жити, де захоче."]},{"v":"1","t":["Євреї, як полонені, сиділи й перебували поза містами, тобто в пустельних місцях; тому, часто ходячи на береги рік, там сиділи на самоті й оплакували свій полон і лихо в молінні. Оскільки за часу володіння благами й свободою вони пишалися й зневажали їх своїми гріхами, то й були позбавлені цих благ, щоб знову їх забажали. Бог завжди так чинить з тими, хто зневажає Його блага; і тих людей, що не відчувають і не знають свого добробуту, позбавляє його, щоб, за словами Золотоустого, привести їх до тями й до згадки про нього.","Прим.: Він так каже: коли, насолоджуючись Його благами, ми цього не відчуваємо, тоді Він переселяє нас у пустелю, де немає благ, щоб, напоумившись через їх утрату, ми знову забажали насолоджуватися ними. Феодорит: ті, хто в смутку, зазвичай займають усамітненіші місця й там оплакують своє лихо. Так і вони, сидячи на берегах рік (а під ріками слід розуміти потоки Євфрату) і міркуючи про спустошення свого головного міста, проливали багато сліз, подібних до струменів рік. А за словами Никити, Вавилоном назване те місце, де змішалася мова тих, хто казав: ходімо, збудуймо собі місто й вежу. Там Бог, зійшовши, змішав мови; тому й місце це назване змішанням мов; і Вавилон — місце змішання не тільки мови, а й правил, і думок, і самого розуму, якому здавалося, що він їх бачить."],"h":"На ріках вавилонських, там ми сиділи й плакали, коли згадували Сіон"},{"v":"2","t":["Музичні, каже, знаряддя, на яких ми співали й прославляли Бога, перебуваючи в Єрусалимі, коли нас забрали до Вавилону, ми повісили на вербах, що росли на берегах рік, які течуть у Вавилоні, бо вони тоді були в нас без ужитку й непотрібні. Єврейські співці взяли їх з собою тільки для нагадування собі про єрусалимське богослужіння й життя, як каже Золотоустий. Або у вищому значенні: зупинили, тобто повісили, свої органи на бездіяльності; так що безплідними деревами — вербами — виразили бездіяльність і невживання псалмів та органів.","Прим.: Органи тоді, за словами Феодорита, були без ужитку, бо закон велів звершувати богослужіння й спів тільки в одному місці — Єрусалимі. Євсевій каже, що інші полонені з юдеїв розкошували й не відчували лиха, що їх спіткало; а священики, левити й співці, тікаючи з міста Вавилону й від спілкування зі своїми ворогами — вавилонянами, сиділи на берегах рік і при течії рік міркували про швидкоплинність справ людського життя; і свої органи ховали на берегах, щоб їх не бачили вороги, а самі, сидячи навпроти органів, замість псалмів ридали, оплакуючи те, що позбавлені псалмоспіву на органах і богослужіння. У цьому відношенні ці слова можна прикладати до тих християн, що зрікаються Христа під час гоніння й захоплюються змішанням від гоніння. Бо Вавилон, як ми сказали, — змішання. Отже, коли хтось із християн зазнає змішання гонінь і замість Христової Церкви житиме серед ворогів і нечестивих, то нехай такий ніколи не забуває про Христову Церкву, у якій духовно відродився через хрещення, і нехай не дається Вавилонові в обман, а, сидячи на ріках, тобто міркуючи про плинність і мінливість справ цього життя, нехай плаче й ридає над своїм падінням.","Прим.: Слова Мефодія Патарського: можливо, дівочі чисті душі в піснях Богові кажуть, що на вербах посеред Вавилону ми повісили наші органи, позначаючи цим, що знаряддя, тобто свої оселі й тіла, вони повісили на висоті чистоти, щоб їх не затопили ріки зла, що ринуть на нас, і не захопили до своєї середини, тобто глибини; тому ми й просимо з плачем, щоб ці органи не втратили чистоти й не впали в хвилі хтивості. А верба часто зображує дівство; бо й питво з розтертого її цвіту гасить спонукання до похоті, а інколи й цілком позбавляє прагнення до дітородіння, як і Гомер сказав, назвавши через це верби згубними для плодів. Бо як це дерево зазвичай росте й квітне при водах, так і дівство може квітнути й удосконалюватися тільки тоді, коли живитиметься Писаннями, щоб хтось міг своє знаряддя поставити в залежність від нього. Бо якщо вавилонські ріки, тобто хтиві течії, що приводять до змішання, бентежать душу, то цнотливість, якою ми зв'язуємо лютість дітородних членів, щоб їх не захопили потоки нестриманості й щоб вони не кидалися нестримно, мов хробаки до гнилі й гною, безперечно, має властивість верб.","Слова цього псалма можна розуміти й інакше. А саме: Сіон і Єрусалим — це рай, наша перша батьківщина, а Вавилон — теперішній світ; ріки цього світу — мінливі справи цього життя. Отже, ставши через переступ полоненими бісів, ми вигнані з раю й дійшли до змішання з цим світом. Тому ми завжди маємо пам'ятати блаженне колишнє райське життя й просити Бога повернути нас знову до раю — нашої колишньої батьківщини — і визволити нас з цієї країни вигнання. Тому цей псалом зазвичай співають у тижні перед сиропусним, коли згадується вигнання Адама, щоб виражалася ця думка."],"h":"На вербах посеред нього повісили ми органи наші"},{"v":"3","t":["Вавилоняни, що полонили нас, питали, веде далі, нас, щоб ми сказали їм кілька слів з божественних пісень і хвал, які ми співали Богові в Єрусалимі, тобто наказували нам співати, бажаючи просто послухати для втіхи або й, за словами Феодорита, щоб посміятися з наших святих і божественних речей. Це слова вавилонян, що сказали нам: заспівайте нам, юдеї, якусь пісню з тих пісень, які ви співали, бувши на Сіоні, в Єрусалимі."],"h":"Бо там питали нас ті, що полонили нас, про слова пісень, і ті, що вели нас, — про спів: заспівайте нам з пісень Сіонських"},{"v":"4","t":["А ми, каже, юдеї, відповідали вавилонянам, що нас питали: як нам співати божественну пісню в чужому місці, поза Єрусалимом, коли закон забороняє нам це? Зауваж, читачу, яким корисним був цей полон і як він виправив юдеїв: бо ті, хто раніше переступав закон Божий посеред своєї батьківщини, нині, за словами Золотоустого, бережуть його на чужій землі. А під чужою землею можна розуміти й кожне серце, що відсторонилося від благочестя й чесноти; такому серцю не слід передавати божественних і небесних таїнств, згідно зі сказаним: не давайте святині псам і не кидайте ваших перлів перед свиньми (Мт. 7:6).","Прим.: З двох причин, як каже один тлумач, юдеї не співали перед вавилонянами: по-перше, тому, що поза Єрусалимом не дозволялося навіть звершувати Пасху чи інші свята; а по-друге, якби вони співали й викладали чудеса, сотворені Богом для визволення нас від єгиптян та інших народів, то вавилоняни не повірили б їм, не допускаючи й того рабства, якого зазнавали євреї. Утім, і ті, хто проповідує Євангеліє безумним, за словами іншого тлумача, співають пісню Господню на чужій землі, бо вона не обробляється Христом. І тим, хто відпав від Церкви, також не слід співати пісень, а тільки ридати й говорити мови, що відповідають нещастю, яке їх спіткало. Це може сказати й той, хто пам'ятає слова: а грішникові сказав Бог: навіщо ти розповідаєш постанови Мої? Бо хто відпав від Церкви, той має взяти ці слова до уваги. І Григорій Богослов разом із Золотоустим каже: коли ми захоплені до Вавилону й у лихе гріховне змішання, то, перебуваючи в цьому місці, не можемо співати божественної пісні, як на чужій землі. Бо доки ми поневолені гріхові, найтяжчому з усіх іноплемінників, доти нам не дозволено говорити про щось божественне, хоч би ми мали знаряддя слова, як вони тоді — псалтирі й гуслі. А коли ми повернемося до чесноти, як до Єрусалима, тоді, склавши з себе чи в собі нову пісню й життя, ми співатимемо нову пісню (у Никити). З Феодорита: це служить на викриття беззаконних юдеїв, що намагаються виконувати закон і звершують його приписи поза визначеними законом місцями."],"h":"Як заспіваємо пісню Господню на чужій землі?"},{"v":"5","t":["Якщо я, юдейський народ, забуду, каже, тебе, місто Єрусалиме, то нехай буде забута, за словами Золотоустого, моя сила й моя дія, тобто нехай я сам стану каліцтвом і розслабленим, або нехай усохне моя рука, щоб я більше не відчував її.","Прим.: Слова Золотоустого: і з цього можеш бачити велику переміну: бо ті, хто щодня чув, що втратять місто, і не дбав про це, нині віддають себе прокляттю, якщо забудуть його. Феодорита: нехай я, каже, не дістану допомоги згори, яку називає правицею. А деякі тлумачі кажуть, що євреї, коли втратили свій улюблений Єрусалим і були відведені до Вавилону, так сумували за ним у своєму серці, що для постійної пам'яті про нього вирізали його на каменях своїх перснів і за кожного погляду на перстень, що був на їхній правій руці, мали нагоду згадувати свою жадану батьківщину. Тому й виголосив ці слова у вигляді прокляття: якщо забуду тебе, Єрусалиме, то нехай буде забута моя права рука... Тому й Золотоустий: послухаймо це й напоумимося. Бо як вони, коли втратили вишній, тобто свій Єрусалим, тоді почали шукати його, так і багато з нас повірять тоді, коли втратять горній Єрусалим; але перші мали надію на повернення, а нам, коли позбудемося того жаданого міста, неможливо буде знову повернутися, бо черв їхній там не вмирає, каже Писання. Тож треба так влаштовувати теперішнє життя, щоб не бути вигнанцями з вишнього міста."],"h":"Якщо забуду тебе, Єрусалиме, нехай забута буде правиця моя"},{"v":"6","t":["Нехай, веде далі, відніметься в мене мій голос, щоб я не міг більше говорити, тобто нехай позбудуся сил діяти — ні ділом, ні словом; ділом тут виражається правиця, про яку сказав вище, а прилипанням язика позначається вимовлене слово. Утім, і ми, християни, з любові до вишнього Єрусалима, нашої вічної батьківщини, зобов'язані вимовляти ті самі слова й прокляття. Або правицею називає доброчесну дію, а язиком — споглядання й знання; бо язик — знак і службове знаряддя слова, а слово — вираз споглядання й пізнання. А гортанню позначає пристрасть горла, тобто насолоду. Отже, нехай буде, каже, забута діяльність через бездіяльність і дія споглядання; нехай прилипне до солодких страв і буде без руху щодо насолоди, яку дають божественні пізнання; і ці прокляття дуже тяжкі. Нехай зазнаю, каже, вищеназваних проклять, якщо раніше за все інше не згадуватиму Єрусалима, бо він стоїть на початку всякої моєї радості, тобто він — початок і голова моєї радості, як моя перша насолода.","Прим.: Золотоустого: дієслово «поставлю тебе на початку» означає те саме, що «почну з тебе», — вислів тих, хто має любов, а краще — пожадання, палке прагнення до нього, тобто до Єрусалима. Феодорита: головою, каже, моєї радості вважаю бачення тебе, твоє нове діяння й торжества, що в тобі бувають. Бо через них я здобуваю справжню насолоду."],"h":"Нехай прилипне язик мій до гортані моєї, якщо не згадаю тебе, якщо не поставлю Єрусалима на початку радості моєї"},{"v":"7","t":["Синами Едому називає арабів та ідумеїв, які, за словами Феодорита, походили від Ісава й допомагали вавилонянам у війні з Єрусалимом. І коли вавилоняни руйнували Єрусалим, тоді й араби з великою старанністю заохочували їх зруйнувати самі основи Єрусалима. Отже, згадай, каже, Господи, віддаючи згаданим арабам та ідумеям праведною карою за те, що вони, попри свою спорідненість з нами, євреями, через одне походження від нашого предка Якова, — тобто через його брата Ісава (бо Ісав звався й Едомом, від якого й ідумеї), — стали для нас нестерпнішими за самих наших ворогів і супротивників через заздрість до нас. А сказавши «синам Едому», додав і «день Єрусалима», тобто: згадай, каже, Господи, і синів Едому, і день нещастя Єрусалима, лише змінивши порядок слів і довільно вживши відразу після родового знахідний відмінок. Або каже: згадай синів Едому, що під час лиха Єрусалима допомагали вавилонянам."],"h":"Згадай, Господи, синам Едому день Єрусалима, коли вони казали: руйнуйте, руйнуйте аж до основ його"},{"v":"8","t":["Як у євреїв є звичай називати людину сином людським, так і дочкою Вавилону називають сам Вавилон. Дочко, каже, Вавилону, неправедна! Вавилоне нещасний через лиха, що, як каже Золотоустий, мають тебе спіткати! А такими словами Давид пророкує про винищення, якого він мав зазнати від царя Кира. Ці слова виголошує весь єврейський народ, сильно бажаючи винищення міста своїх ворогів. А відплатою, якою, за висловом, ти відплатила нам, називають завдане зло, тобто спустошення й гноблення, яких ти, Вавилоне, завдав нам, євреям; тут грецький префікс у слові «відплата» зайвий, як ми зауважили й у 7-му псалмі, пояснюючи слова: якщо я відплатив злом тим, хто відплачує мені злом.","Прим.: Дочкою Вавилону зветься столиця Вавилону порівняно з усією вавилонською країною, яка представляється у вигляді матері, а її місто — у вигляді дочки, як ми сказали й у 44-му псалмі, пояснюючи слова «дочка Тиру з дарами», і в 72-му псалмі, пояснюючи слова «у брамах дочки Сіонової».","Прим.: Феодорита: блаженним вважається Кир як той, що покарав їх і звільнив юдеїв, — не за те, що він був вихованцем справжнього благочестя, а за те, що сподобив благочестивий народ свободи й звелів збудувати божественний храм. Далі, Бог приймає й малі плоди й винагороджує великими віддяками. Так Він прославив удовицю за дві лепти. Золотоустого: це вислови пристрасті полонених! Бо якщо хочеш знати налаштування Давида, то послухай, що він каже: якщо я відплатив тим, хто відплачує мені злом (тобто я не відплатив), — і як він стає вище за дозволену законом рівномірність. А коли передає пристрасті інших, то зображує лють і смуток, що й тепер зробив, виставивши сильне бажання юдеїв. Але не такий Новий Завіт: у ньому нам велиться напувати й годувати ворогів і молитися за тих, хто нас кривдить."],"h":"Дочко вавилонська, нещасна! Блаженний, хто віддасть тобі відплату твою, якою ти відплатила нам!"},{"v":"9","t":["Юдеї поширюють свій гнів і на незрілий вік отроків і ублажають того, хто жорстоко й нелюдяно розбив малих дітей і отроків вавилонських. Але євангельські повеління й вдача в нас, християн, як учнів лагідного й людинолюбного Ісуса Христа, не такі — не жорстокі й не нелюдяні. Зовсім не такі, бо наш Владика Христос звелів любити навіть наших ворогів і берегти їх. Але те, що в цьому псалмі може бути легко прийняте у вищому значенні, треба й розуміти в ньому. Отже, під синами Едому ми маємо розуміти бісів, що велять одне одному руйнувати багатства нашої душі до основи. Бо під Єрусалимом маємо уявляти душу. А нещасний Вавилон — це нечестя й гріх, що спустошив і підкорив собі благочестя й чесноту. А хто винищив це нечестя й гріх, той блаженний. Немовлята цього нечестя — новонароджені пристрасні помисли, бо вони дитячі й безтямні. Хто ці помисли перемагає й розбиває об камінь віри (а цей камінь, за словами Павла, — Христос) і так винищує їх, той блаженний.","Прим.: Слова Феодорита: оскільки й вони, вавилоняни, вчинили жорстоко з немовлятами юдеїв, то пророк передрікає їм рівну кару. Василія: у цьому псалмі ублажається не той, хто будь-як убиває вавилонських дітей, а він, по-перше, хоче, щоб винищувалися нещодавно народжені немовлята, яким не дозволено дійти до віку, щоб вони не наробили дуже багато зла; по-друге, щоб їх знищували не будь-яким способом, а розбивали об камінь. Бо він називає щасливим того, хто своєю мудрістю володіє породженнями змішаного розуму, що зветься вавилонським, і переможе їх, а потім велить розбивати їх об камінь, яким є Христос. І хто вражає негідні вчення словом істини, той розбиває вавилонських немовлят об камінь. Отже, якщо діти вавилонян — учення неправославних, бо вони приводять до змішання душу того, хто добровільно їх приймає, то влучно бажає, щоб вавилонські немовлята (які в Писанні звуться винятково й халдейським насінням) були взяті й розбиті об камінь. Кирила: вавилонською дочкою може бути названий і гріх, якщо справді Вавилон, як пояснюють, — змішання, а ділом — переступ розуму, неспокійного й неутвердженого, а краще сказати — того, що прийшов до змішання, злиття й ніби сп'янів від багаторазового схилення до зла. Бо душа спершу приходить до сум'яття, і тоді вже звершує гріх ділом. Слова святого Дорофея: гріх зветься нещасним, бо він не сутнісний і не має справжнього буття, а лише дістає існування від нашої поведінки й знову через чесноту обертається на ніщо. Йому ми віддали свою волю й у відплату дістали гріх, який і має бути йому повернений, тобто більше не чинитися. Вавилонськими немовлятами, що їх ударяють і розбивають об камінь, безпомилково можеш назвати насіння зла й початки гріхів, що спричиняють сум'яття, і пристрасні помисли, що щойно з'являються; їх слід винищувати спасенним словом (бо камінь — Христос), щоб вони не зростали й не доходили до дії, а знищувалися, доки не стали досконалими. Отже, слід виходити ніби з північної землі — з холодного й мертвого налаштування розуму — на Сіон, тобто в істину, щоб мати поняття про Христову Церкву, у якій, перебуваючи, побачимо, що вгодне Богові, і не дамо злу в нас ні початку, ні місця, де б воно могло зрости й дійти до дії, а будемо блаженні, пануючи над дитячими й безтямними помислами, розбиваючи й так гублячи їх об камінь віри (у Никити)."],"h":"Блаженний, хто візьме й розіб'є немовлят твоїх об камінь!"}]};
